import React from 'react';
import { useNavigate } from 'react-router-dom';

const services = [
  {
    id: 1,
    title: "Tổ chức tiệc cưới",
    desc: "Tổ chức lễ cưới chuyên nghiệp, sang trọng và theo yêu cầu cá nhân hóa cho từng cặp đôi.",
    path: "/service/wedding"
  },
  {
    id: 2,
    title: "Sinh nhật & Kỷ niệm",
    desc: "Trang trí và tổ chức tiệc sinh nhật, kỷ niệm với nhiều phong cách và gói dịch vụ linh hoạt.",
    path: "/service/birthday"
  },
  {
    id: 3,
    title: "Sự kiện công ty",
    desc: "Tổ chức hội nghị, gala dinner, team building với quy mô từ nhỏ đến lớn, chuyên nghiệp và hiệu quả.",
    path: "/service/corporate"
  },
  {
    id: 4,
    title: "Trang trí tiệc theo chủ đề",
    desc: "Cung cấp dịch vụ trang trí không gian tiệc theo các chủ đề độc đáo và phong cách.",
    path: "/service/decor"
  }
];

function Home() {
  const navigate = useNavigate();
  const isLoggedIn = !!JSON.parse(localStorage.getItem("currentUser"));

  const handleClick = (path) => {
    if (isLoggedIn) {
      navigate(path);
    } else {
      alert("Vui lòng đăng nhập để xem chi tiết dịch vụ.");
      navigate("/login");
    }
  };

  return (
    <div className="container py-5">
      <div className="bg-dark text-white p-5 rounded text-center mb-5">
      <h2 className="display-5">Trọn gói tổ chức sự kiện</h2>
      <p className="lead">Chuyên nghiệp – Chỉnh chu – Cá nhân hóa</p>
    </div>
    <div className="row text-center">
      {services.map(s => (
        <div className="col-md-6 mb-4" key={s.id}>
          <div className="border rounded p-4 h-100 bg-light">
            <h4 className="text-dark">{s.title}</h4>
            <p className="text-muted">{s.desc}</p>
            <button className="btn btn-dark mt-2" onClick={() => handleClick(s.path)}>Xem chi tiết</button>
          </div>
        </div>
      ))}
    </div>
  </div>
  );
}

export default Home;
